import {expect, test, type Page} from '@playwright/test';
import {addDays, mockApi, signIn, today} from './mock-api';
import {offersData} from './offers-fixtures';

/**
 * Revisión 1 · E6–E7 «Ofertas» in the Gestor: an offer's validity and
 * conditions with the cost of a need, «Pedir presupuesto» with personal
 * links shared by hand, the received proposals (only administrators
 * decide), renewals generated by Ox Eye, and what a guest never sees.
 */

test.use({locale: 'es-ES', timezoneId: 'Atlantic/Canary'});

async function openTab(
  page: Page,
  tab: 'offers' | 'requests' | 'inbox' | 'renewals',
) {
  await page.locator(`#lx-ctab-${tab}`).click();
  await expect(page.locator(`#lx-ctab-${tab}`)).toHaveAttribute(
    'aria-selected',
    'true',
  );
}

test.describe('E6 · offer terms in the offer sheet', () => {
  test('three dates apart, seasons, supplements and the cost of a need', async ({
    page,
  }) => {
    await mockApi(page, offersData());
    await signIn(page, 'Elvis', '#logistica/catalogo/ficha/oferta/o1');
    const terms = page.locator('#lx-offer-terms');
    await expect(terms).toBeVisible();
    await expect(page.locator('#lx-offer-validity')).toContainText(
      'Vence en 20 días',
    );
    await expect(terms).toContainText('Verano');
    await expect(terms).toContainText('Transporte');
    await expect(terms).toContainText('Lastres');
    // Prices before tax; the total is an estimate, never a certainty.
    await expect(terms).toContainText(/sin impuestos|antes de impuestos/i);
    await expect(terms).toContainText(/estimación/i);
    await expect(page.locator('#lx-offer-terms-legacy')).toHaveCount(0);

    // A seasonal price needs dates: those of the next event, said so.
    await expect(page.locator('#lx-offer-need-event')).toContainText(
      'Fechas del evento «Navidad en la Plaza del Cristo»',
    );
    await expect(page.locator('#lx-offer-need-breakdown')).toContainText('≈');
    await expect(page.locator('#lx-offer-need-breakdown')).toContainText(
      'Transporte',
    );
    // Changing the dates drops the note: they are the user's now.
    await page.locator('#lx-offer-need-days').fill('2');
    await expect(page.locator('#lx-offer-need-event')).toBeVisible();
    await page.locator('#lx-offer-need-from').fill(addDays(today, 40));
    await page.locator('#lx-offer-need-from').press('Tab');
    await expect(page.locator('#lx-offer-need-event')).toHaveCount(0);

    // History loads when opened: both versions, newest first.
    await page.locator('#lx-offer-versions-box > summary').click();
    const versions = page.locator('#lx-offer-versions-box li');
    await expect(versions).toHaveCount(2);
    await expect(versions.first()).toContainText('160 € → 170 €');
  });

  test('with no event ahead a seasonal offer gives no total until dates are set', async ({
    page,
  }) => {
    await mockApi(page, {...offersData(), events: []});
    await signIn(page, 'Elvis', '#logistica/catalogo/ficha/oferta/o1');
    await expect(page.locator('#lx-offer-need-breakdown')).toContainText(
      'Sin total',
    );
    await expect(page.locator('#lx-offer-need-event')).toHaveCount(0);
    await expect(page.locator('#lx-offer-need')).toContainText(
      'Con fechas se aplica la tarifa de su temporada.',
    );
  });

  test('an offer recorded before versions says its data is the old one', async ({
    page,
  }) => {
    await mockApi(page, offersData());
    await signIn(page, 'Elvis', '#logistica/catalogo/ficha/oferta/o2');
    await expect(page.locator('#lx-offer-terms-legacy')).toBeVisible();
  });

  test('«Renegociar» opens a request for the same company', async ({page}) => {
    await mockApi(page, offersData());
    await signIn(page, 'Elvis', '#logistica/catalogo/ficha/oferta/o1');
    await page.locator('#lx-offer-renegotiate').click();
    const sheet = page.locator('#lx-request-sheet');
    await expect(sheet).toBeVisible();
    await expect(sheet).toContainText('Renegociar');
    await expect(sheet.locator('#lx-qr-companyIds')).toContainText(
      'Carpas Demo',
    );
  });
});

test.describe('E7 · asking for quotes', () => {
  test('creates personal links that the user shares by hand', async ({
    page,
  }) => {
    const mock = await mockApi(page, offersData());
    await signIn(page, 'Elvis', '#logistica/catalogo');
    await page.locator('#lx-request-new').click();
    const sheet = page.locator('#lx-request-sheet');
    await sheet.locator('#lx-qr-title').fill('2 escenarios de 8 × 6 m');
    await sheet.locator('#lx-qr-quantity').fill('2');
    await sheet.locator('#lx-qr-days').fill('2');
    await sheet.locator('#lx-qr-companyIds').click();
    await page
      .locator('#lx-qr-companyIds-listbox [role="option"][data-value="c1"]')
      .click();
    await page
      .locator('#lx-qr-companyIds-listbox [role="option"][data-value="c2"]')
      .click();
    await page.keyboard.press('Escape');
    await page.locator('#lx-request-submit').click();

    const links = page.locator('#lx-request-created-links .lx-sharelink');
    await expect(links).toHaveCount(2);
    // localhost: the address only works on this computer.
    await expect(page.locator('#lx-request-created-local')).toContainText(
      'npm run equipo',
    );
    const first = links.first();
    await expect(first.locator('.lx-sharelink__url')).toContainText(
      '#logistica/proveedor/',
    );
    const mail = first.locator('[data-action="mail"]');
    await expect(mail).toHaveAttribute(
      'href',
      /^mailto:ventas%40carpasdemo\.es\?subject=/,
    );
    // The server never mails anyone: the request carries no address or message.
    const [created] = mock.calls('POST', '/quote-requests');
    expect(created.body).toMatchObject({
      need: {title: '2 escenarios de 8 × 6 m', quantity: 2, days: 2},
      companyIds: ['c1', 'c2'],
      linkDays: 7,
    });

    await page.locator('#lx-request-done').click();
    await expect(page.locator('#lx-ctab-requests')).toHaveAttribute(
      'aria-selected',
      'true',
    );
    await expect(page.locator('#lx-requests-list')).toContainText(
      '2 escenarios de 8 × 6 m',
    );
  });

  test('a lost link is renewed and the old one stops working', async ({
    page,
  }) => {
    const mock = await mockApi(page, offersData());
    await signIn(page, 'Elvis', '#logistica/catalogo');
    await openTab(page, 'requests');
    await page.locator('[data-request-id="qr1"]').click();
    const detail = page.locator('#lx-request-detail');
    await expect(detail.locator('[data-link-id="ql-c3"]')).toContainText(
      'No tenemos carpas libres',
    );
    await detail
      .locator('[data-link-id="ql-c2"] [data-action="renew"]')
      .click();
    await expect(
      page.locator('#lx-request-links-sheet .lx-sharelink'),
    ).toHaveCount(1);
    expect(
      mock.calls('POST', '/quote-requests/qr1/links/ql-c2/renew'),
    ).toHaveLength(1);
    expect(
      (mock.quoteRequests[0].links as {id: string; status: string}[]).find(
        l => l.id === 'ql-c2',
      )?.status,
    ).toBe('revoked');
  });

  test('the comparison marks a pending proposal and never ranks it', async ({
    page,
  }) => {
    await mockApi(page, offersData());
    await signIn(page, 'Elvis', '#logistica/catalogo');
    await openTab(page, 'requests');
    await page.locator('[data-request-id="qr1"]').click();
    const compare = page.locator('#lx-request-compare');
    const pending = compare.locator('li[data-pending]');
    await expect(pending).toHaveCount(1);
    await expect(pending).toContainText('Pendiente de aprobar');
    await expect(pending).not.toHaveAttribute('data-rank', /.*/);
    await expect(pending.locator('.lx-medal')).toHaveCount(0);
    await expect(compare.locator('li[data-rank="1"]')).toHaveCount(1);
  });

  test('closing a request asks first', async ({page}) => {
    const mock = await mockApi(page, offersData());
    await signIn(page, 'Elvis', '#logistica/catalogo');
    await openTab(page, 'requests');
    await page.locator('[data-request-id="qr1"]').click();
    await page.locator('#lx-request-close').click();
    await page.locator('#lx-request-close-confirm').click();
    await expect.poll(() => mock.quoteRequests[0].status).toBe('closed');
    expect(mock.calls('POST', '/quote-requests/qr1/close')[0].body).toEqual({
      version: 1,
    });
  });
});

test.describe('E7 · received proposals', () => {
  test('an administrator approves one into the catalogue', async ({page}) => {
    const mock = await mockApi(page, offersData());
    await signIn(page, 'Elvis', '#logistica/catalogo');
    await expect(
      page.locator('#lx-ctab-inbox .lx-segtabs__count'),
    ).toContainText('2');
    await openTab(page, 'inbox');
    await page.locator('[data-proposal-id="p1"]').click();
    const sheet = page.locator('#lx-proposal-sheet');
    await expect(sheet.locator('#lx-proposal-company')).toHaveAttribute(
      'data-match',
      'known',
    );
    await expect(sheet.locator('#lx-proposal-flags')).toContainText(
      'por verificar',
    );
    await sheet.locator('#lx-proposal-approve').click();
    await sheet.locator('#lx-proposal-approve-confirm').click();
    await expect(sheet).toHaveCount(0);
    expect(mock.calls('POST', '/proposals/p1/approve')[0].body).toEqual({
      version: 1,
    });
    await page.locator('#lx-inbox-tab-approved').click();
    await expect(
      page.locator('#lx-inbox-list [data-proposal-id="p1"]'),
    ).toContainText('aprobada por Elvis');
  });

  test('the open form under an existing name is flagged for checking', async ({
    page,
  }) => {
    await mockApi(page, offersData());
    await signIn(page, 'Elvis', '#logistica/catalogo');
    await openTab(page, 'inbox');
    await page.locator('[data-proposal-id="p2"]').click();
    const sheet = page.locator('#lx-proposal-sheet');
    await expect(sheet.locator('#lx-proposal-company')).toHaveAttribute(
      'data-match',
      'check',
    );
    await expect(sheet.locator('#lx-proposal-company')).toContainText(
      'Toldos Sur',
    );
    await expect(sheet.locator('#lx-proposal-flags')).toContainText(
      'Falta el impuesto',
    );
  });

  test('rejecting needs a reason', async ({page}) => {
    const mock = await mockApi(page, offersData());
    await signIn(page, 'Elvis', '#logistica/catalogo');
    await openTab(page, 'inbox');
    await page.locator('[data-proposal-id="p2"]').click();
    const sheet = page.locator('#lx-proposal-sheet');
    await sheet.locator('#lx-proposal-reject').click();
    await sheet.locator('#lx-proposal-reject-confirm').click();
    await expect(sheet.locator('#lx-proposal-reason')).toBeFocused();
    expect(mock.calls('POST', '/proposals/p2/reject')).toHaveLength(0);
    await sheet.locator('#lx-proposal-reason').fill('No es de Toldos Sur.');
    await sheet.locator('#lx-proposal-reject-confirm').click();
    await expect(sheet).toHaveCount(0);
    expect(mock.calls('POST', '/proposals/p2/reject')[0].body).toEqual({
      version: 1,
      reason: 'No es de Toldos Sur.',
    });
  });

  test('a proposal received by phone enters the inbox', async ({page}) => {
    const mock = await mockApi(page, offersData());
    await signIn(page, 'Elvis', '#logistica/catalogo');
    await openTab(page, 'inbox');
    await page.locator('#lx-inbox-manual').click();
    await expect(page.locator('#lx-manual-sheet')).toBeVisible();
    const form = page.locator('#lx-mp-form');
    const next = page.locator('#lx-mp-next');
    await page.locator('#lx-mp-company-name').fill('Lonas Atlántico');
    await next.click();
    await expect(form).toHaveAttribute('data-step', 'price:0');
    await page.locator('#lx-mp-products-0-name').fill('Carpa 5x5');
    await page.locator('#lx-mp-products-0-price').fill('120');
    for (const step of ['extras:0', 'products', 'tax', 'dates', 'review']) {
      await next.click();
      await expect(form).toHaveAttribute('data-step', step);
    }
    await next.click();
    await expect.poll(() => mock.calls('POST', '/proposals').length).toBe(1);
    const body = mock.calls('POST', '/proposals')[0].body as {
      origin: string;
      proposal: Record<string, unknown>;
    };
    expect(body.origin).toBe('Por teléfono');
    expect('privacyAccepted' in body.proposal).toBe(false);
    await expect(page.locator('#lx-inbox-list')).toContainText(
      'Lonas Atlántico',
    );
  });

  test('the team reviews but does not decide', async ({page}) => {
    await mockApi(page, offersData());
    await signIn(page, 'Equipo', '#logistica/catalogo');
    await openTab(page, 'inbox');
    await expect(page.locator('#lx-inbox-team-note')).toBeVisible();
    await page.locator('[data-proposal-id="p1"]').click();
    const sheet = page.locator('#lx-proposal-sheet');
    await expect(sheet.locator('#lx-proposal-locked')).toContainText(
      'Pendiente de un administrador',
    );
    await expect(sheet.locator('#lx-proposal-approve')).toHaveCount(0);
  });
});

test.describe('E6 · renewals', () => {
  test('generated by Ox Eye; the notice is an administrator setting', async ({
    page,
  }) => {
    const mock = await mockApi(page, offersData());
    await signIn(page, 'Elvis', '#logistica/catalogo');
    await openTab(page, 'renewals');
    const card = page.locator('[data-renewal-id="rn1"]');
    await expect(card).toContainText('Generada por Ox Eye');
    await expect(card).toContainText('Carpas Demo · Carpa 6x6');
    // Controlled radios: they turn on once the server has saved.
    await page.locator('#lx-notice-days-60').click();
    await expect.poll(() => mock.offerSettings.renewalNoticeDays).toBe(60);
    expect(mock.calls('PATCH', /offer-settings$/)[0].body).toEqual({
      renewalNoticeDays: 60,
      version: 0,
    });
  });

  test('the open link is shown once, after an administrator turns it on', async ({
    page,
  }) => {
    await mockApi(page, offersData());
    await signIn(page, 'Elvis', '#logistica/catalogo');
    await openTab(page, 'renewals');
    await page.locator('#lx-open-link-on').click();
    const box = page.locator('#lx-open-link');
    await expect(box.locator('.lx-sharelink__url')).toContainText(
      '#logistica/proveedor/abierto/',
    );
    await expect(page.locator('#lx-open-link-local')).toBeVisible();
  });

  test('the team cannot change the notice', async ({page}) => {
    await mockApi(page, offersData());
    await signIn(page, 'Equipo', '#logistica/catalogo');
    await openTab(page, 'renewals');
    await expect(page.locator('#lx-notice-days-60')).toBeDisabled();
  });

  test('the generated task carries its mark and leads to the offer', async ({
    page,
  }) => {
    await mockApi(page, offersData());
    await signIn(page, 'Elvis', '#logistica/tareas/ficha/tarea/t-rn1');
    const mark = page.locator('#lx-task-sheet #lx-task-renewal');
    await expect(mark).toContainText(
      'Generada por Ox Eye · renegociación de Carpa 6x6',
    );
    await mark.locator('#lx-task-renewal-offer').click();
    await expect(page.locator('#lx-offer-terms')).toBeVisible();
  });

  test('a guest sees the task without the mark', async ({page}) => {
    const mock = await mockApi(page, offersData());
    await signIn(page, 'Invitado', '#logistica/tareas/ficha/tarea/t-rn1');
    await expect(page.locator('#lx-task-sheet')).toBeVisible();
    await expect(page.locator('#lx-task-renewal')).toHaveCount(0);
    expect(mock.calls('GET', /offer-renewals/)).toHaveLength(0);
  });
});

test('E6–E7 · a guest never sees the contracting views nor asks for them', async ({
  page,
}) => {
  const mock = await mockApi(page, offersData());
  await signIn(page, 'Invitado', '#logistica/catalogo');
  await expect(page.locator('#lx-ctab-requests')).toHaveCount(0);
  await expect(page.locator('#lx-request-new')).toHaveCount(0);
  const e7 =
    /offer-versions|quote-requests|proposals|offer-settings|offer-renewals/;
  expect(mock.calls('GET', e7)).toHaveLength(0);
});
